-- ============================================================
-- 20260733_kb_chunks.sql
-- GA 챗봇 지식베이스: kb_chunks 테이블 + RLS + 'kb' 역할 + 시드 47청크
-- 실행: Supabase SQL Editor에서 전체 실행 (BEGIN~COMMIT 원자 반영)
-- ============================================================
BEGIN;

-- ------------------------------------------------------------
-- [1] admin_roles CHECK 확장: 'kb' 역할 추가
-- 기존 허용값(11종 + 레거시 zoom/meeting_room)에 값을 '추가'만 하므로
-- 기존 행은 전부 새 CHECK를 만족 → 20260730에서 겪은 ALTER 실패 위험 없음
-- ------------------------------------------------------------
ALTER TABLE admin_roles DROP CONSTRAINT IF EXISTS admin_roles_role_check;
ALTER TABLE admin_roles ADD CONSTRAINT admin_roles_role_check
  CHECK (role IN (
    'dashboard','booking','approval','room','user','visitor',
    'book','notification','notice','pointer','super',
    'kb',                     -- ★ 신규: KB 관리 탭
    'zoom','meeting_room'     -- 레거시 (데이터 0건, 보존용)
  ));

-- ------------------------------------------------------------
-- [2] kb_chunks 테이블
-- bot_id: 챗봇 코어/지식 분리 원칙의 DB 구현 ('ga' | 'space' | ...)
-- updated_by: profiles 참조 + SET NULL — 퇴사(profiles DELETE) 시에도
--             청크 행이 깨지지 않도록 (manualDepartUser 경로 대비)
-- ------------------------------------------------------------
CREATE TABLE kb_chunks (
  id          text PRIMARY KEY,
  bot_id      text NOT NULL DEFAULT 'ga',
  category    text NOT NULL,
  doc         text NOT NULL,
  section     text NOT NULL,
  content     text NOT NULL,
  keywords    text[] NOT NULL DEFAULT '{}',
  contacts    text[] NOT NULL DEFAULT '{}',
  related     text[] NOT NULL DEFAULT '{}',
  status      text NOT NULL DEFAULT 'ok'
              CHECK (status IN ('ok','image_only','pdf_only')),
  sensitive   boolean NOT NULL DEFAULT false,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  uuid REFERENCES profiles(id) ON DELETE SET NULL
);

CREATE INDEX kb_chunks_bot_id_idx ON kb_chunks (bot_id, category);

-- ------------------------------------------------------------
-- [3] 갱신 추적 트리거
-- 프론트에 맡기지 않고 DB가 보장 (경로가 늘어도 기록 누락 없음 —
-- 퇴사 회수 트리거와 같은 논리). BEFORE UPDATE 단순 touch라 부작용 없음
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION kb_chunks_touch()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

CREATE TRIGGER kb_chunks_touch_trg
  BEFORE UPDATE ON kb_chunks
  FOR EACH ROW EXECUTE FUNCTION kb_chunks_touch();

-- ------------------------------------------------------------
-- [4] RLS
-- 읽기/쓰기 모두 has_admin_role('kb') — super는 함수 정의상 자동 통과
-- 챗봇 런타임은 service_role로 읽으므로(RLS 우회) 별도 anon 정책 없음
-- → credential 포함 청크가 로그인 없이 노출되는 경로를 차단
-- ------------------------------------------------------------
ALTER TABLE kb_chunks ENABLE ROW LEVEL SECURITY;

CREATE POLICY kb_chunks_select_kb_admin ON kb_chunks
  FOR SELECT USING (has_admin_role('kb'));

CREATE POLICY kb_chunks_insert_kb_admin ON kb_chunks
  FOR INSERT WITH CHECK (has_admin_role('kb'));

CREATE POLICY kb_chunks_update_kb_admin ON kb_chunks
  FOR UPDATE USING (has_admin_role('kb')) WITH CHECK (has_admin_role('kb'));

CREATE POLICY kb_chunks_delete_kb_admin ON kb_chunks
  FOR DELETE USING (has_admin_role('kb'));

-- ------------------------------------------------------------
