-- ------------------------------------------------------------
-- [6] 자기 검증 — 실패 시 전체 롤백
-- ------------------------------------------------------------
DO $$
DECLARE
  cnt int;
  broken int;
BEGIN
  SELECT count(*) INTO cnt FROM kb_chunks WHERE bot_id = 'ga';
  IF cnt <> 47 THEN
    RAISE EXCEPTION '시드 청크 수 불일치: % (기대 47)', cnt;
  END IF;

  -- related 참조 무결성: 존재하지 않는 청크 id를 가리키면 실패
  SELECT count(*) INTO broken
  FROM kb_chunks c, unnest(c.related) r
  WHERE NOT EXISTS (SELECT 1 FROM kb_chunks t WHERE t.id = r);
  IF broken > 0 THEN
    RAISE EXCEPTION 'related 깨진 참조 %건', broken;
  END IF;

  RAISE NOTICE 'kb_chunks 검증 통과: 47청크, 참조 무결성 OK';
END;
$$;

COMMIT;

